/**
 * Compose the root registry.json from its parts, then `shadcn build` → public/r/*.json.
 *
 *   registry/oc/themes/registry.json   generated by `pnpm tokens`
 *   registry/oc/blocks/registry.json   hand-written blocks/components
 *   registry/oc/templates/registry.json  starter pages (registry:page) composing @oc blocks
 *
 * Also syncs the per-block tsconfig path aliases templates rely on (see registry-aliases.ts).
 *
 * shadcn's `include` resolves file paths relative to each included file and forbids `../`,
 * so we merge into one root file with repo-relative paths instead.
 */
import { execFileSync } from "node:child_process"
import { readFile, writeFile } from "node:fs/promises"

import { config, ownRegistryDependency } from "../lib/config"

import { syncTsconfigPaths } from "./registry-aliases"

const PARTS = [
  "registry/oc/themes/registry.json",
  "registry/oc/blocks/registry.json",
  "registry/oc/templates/registry.json",
  "registry/oc/lib/registry.json", // generated by pnpm tokens
]

async function main() {
  const items: { name: string; registryDependencies?: string[] }[] = []
  for (const p of PARTS) items.push(...(JSON.parse(await readFile(p, "utf8")) as { items: { name: string }[] }).items)

  const dupes = items.map((i) => i.name).filter((n, i, all) => all.indexOf(n) !== i)
  if (dupes.length) throw new Error(`duplicate registry item names: ${dupes.join(", ")}`)

  const registry = {
    $schema: "https://ui.shadcn.com/schema/registry.json",
    name: config.namespace.slice(1),
    homepage: config.repositoryUrl,
    items: items.map((item) => ({ ...item, ...(item.registryDependencies ? { registryDependencies: item.registryDependencies.map((d) => ownRegistryDependency(d)) } : {}) })),
  }
  await writeFile("registry.json", JSON.stringify(registry, null, 2) + "\n")
  console.log(`✓ registry.json: ${items.length} items`)

  if (!(await syncTsconfigPaths({ write: true }))) console.log("✓ tsconfig.json: block path aliases updated")

  if (!process.argv.includes("--no-build"))
    execFileSync("pnpm", ["exec", "shadcn", "build"], { stdio: "inherit" })
}

main()
